	while n > 1:
		if prime[i]:
			count = 0
			while n % i == 0:
				count += 1
				n = n // i
			if count % k != 0:
				a.append((i, count % k))
				b.append((i, k - count % k))
		i += 1
	return [tuple(a), tuple(b)]

