def bootstrap(f, stack=[]):

	def wrappedfunc(*args, **kwargs):
		if stack:
			return f(*args, **kwargs)
		else:
			to = f(*args, **kwargs)
			while True:
				if type(to) is GeneratorType:
					stack.append(to)
					to = next(to)
				else:
					stack.pop()
					if not stack:
						break
					to = stack[-1].send(to)
			return to
	return wrappedfunc

def DFS(adj, v):
	parent = {}
	dp = [0] * len(adj)

	@bootstrap
	def DFS_use(adj, s):
		dp[s] = [0, 1]
		for (i, w) in adj[s]:
			if i not in parent:
				parent[i] = s
				x = (yield DFS_use(adj, i))
				if w:
					dp[s][0] += x[1]
				else:
					dp[s][0] += x[0]
				dp[s][1] += x[1]
		yield dp[s]
	ans = [0]

	def reroute(s, i, w):
		dp[s][1] -= dp[i][1]
		if w:
			dp[s][0] -= dp[i][1]
			dp[i][0] += dp[s][1]
		else:
			dp[s][0] -= dp[i][0]
			dp[i][0] += dp[s][0]
		dp[i][1] += dp[s][1]

	@bootstrap
	def solve(adj, s):
		for (i, w) in adj[s]:
			if i not in parent:
				parent[i] = s
				reroute(s, i, w)
				ans[0] += ncr(dp[i][0], 2) * 2 if dp[i][0] >= 2 else 0
				x = (yield solve(adj, i))
				reroute(i, s, w)
		yield dp[s]
	for s in v:
		if s not in parent:
			parent[s] = None
			DFS_use(adj, s)
	parent = {}
	for s in v:
		if s not in parent:
			parent[s] = None
			ans[0] += ncr(dp[s][0], 2) * 2 if dp[s][0] >= 2 else 0
			solve(adj, s)
	return ans[0]
