def bootstrap(f, stack=[]):

	def wrappedfunc(*args, **kwargs):
		if stack:
			return f(*args, **kwargs)
		else:
			to = f(*args, **kwargs)
			while True:
				if type(to) is GeneratorType:
					stack.append(to)
					to = next(to)
				else:
					stack.pop()
					if not stack:
						break
					to = stack[-1].send(to)
			return to
	return wrappedfunc

def solve():
	(N, K) = getInts()
	graph = col.defaultdict(set)
	dp = [[0 for k in range(K + 1)] for n in range(N)]
	for n in range(N - 1):
		(U, V) = getInts()
		U -= 1
		V -= 1
		graph[U].add(V)
		graph[V].add(U)
	visited = set()

	@bootstrap
	def dfs(node):
		dp[node][0] = 1
		visited.add(node)
		for neighbour in graph[node]:
			if neighbour not in visited:
				yield dfs(neighbour)
				for k in range(K):
					dp[node][k + 1] += dp[neighbour][k]
		yield
	dfs(0)
	ans = 0
	visited = set()
	for n in range(N):
		visited.add(n)
		ans += dp[n][K]
		tmp = 0
		for neighbour in graph[n]:
			if neighbour not in visited:
				for k in range(1, K):
					tmp += dp[neighbour][k - 1] * (dp[n][K - k] - dp[neighbour][K - k - 1])
		tmp //= 2
		ans += tmp
	return ans
