	corners = [(r, c) for (r, row) in enumerate(sq) for (c, count) in enumerate(row) if count == 1]
	if len(corners) != 4:
		return False
	(left, right, top, bottom) = (corners[0][1], corners[3][1], corners[0][0], corners[3][0])
	if right == left + 1 or bottom == top + 1:
