class BIT:

	def __init__(self, n):
		self.n = n
		self.bit = [0] * (self.n + 1)

	def init(self, init_val):
		for (i, v) in enumerate(init_val):
			self.add(i, v)

	def add(self, i, x):
		i += 1
		while i <= self.n:
			self.bit[i] += x
			i += i & -i

	def sum(self, i, j):
		return self._sum(j) - self._sum(i)

	def _sum(self, i):
		res = 0
		while i > 0:
			res += self.bit[i]
			i -= i & -i
		return res

class RangeAddBIT:

	def __init__(self, n):
		self.n = n
		self.bit1 = BIT(n)
		self.bit2 = BIT(n)

	def init(self, init_val):
		self.bit2.init(init_val)

	def add(self, l, r, x):
		self.bit1.add(l, x)
		self.bit1.add(r, -x)
		self.bit2.add(l, -x * l)
		self.bit2.add(r, x * r)

	def sum(self, l, r):
		return self._sum(r) - self._sum(l)

	def _sum(self, i):
		return self.bit1._sum(i) * i + self.bit2._sum(i)

	def __str__(self):
		arr = [self.sum(i, i + 1) for i in range(self.n)]
		return str(arr)
