class DisjoinSet:

	def __init__(self, n):
		self.n = n
		self.dad = [i for i in range(n + 1)]
		self.cant = [1] * (n + 1)

	def SetOf(self, n):
		if self.dad[n] == n:
			return n
		self.dad[n] = self.SetOf(self.dad[n])
		return self.dad[n]

	def Merge(self, a, b):
		(a, b) = (self.SetOf(a), self.SetOf(b))
		if a != b:
			if self.cant[b] > self.cant[a]:
				(a, b) = (b, a)
			self.cant[a] += self.cant[b]
			self.dad[b] = a
			return True
		return False

def Kruskal(l, n):
	l.sort()
